local ArbalestMaker = {}
local PRODUCTS = {
    simple_wood_arbalest = { name = "Preprost leseni samostrel", woodCost = 4, ironCost = 1, ropeCost = 1, time = 6, cost = 130, attack = 38, happiness = 1, description = "Preprost leseni samostrel za strelce." },
    steel_prod_arbalest = { name = "Jeklenoluk samostrel", woodCost = 3, steelCost = 2, ironCost = 1, ropeCost = 1, time = 9, cost = 380, attack = 55, happiness = 2, prestige = 3, description = "Jeklenoluk samostrel za trgovce." },
    silver_inlaid_arbalest = { name = "Srebrnovloženi samostrel", woodCost = 3, steelCost = 2, silverCost = 1, ironCost = 1, ropeCost = 1, time = 12, cost = 880, attack = 70, happiness = 2, prestige = 8, description = "Srebrnovloženi samostrel za plemiče." },
    gold_trimmed_arbalest = { name = "Zlatookrasni samostrel", woodCost = 3, steelCost = 2, goldCost = 1, silverCost = 1, ironCost = 1, ropeCost = 1, time = 16, cost = 1900, attack = 82, happiness = 3, prestige = 18, description = "Zlatookrasni samostrel za visoke plemiče." },
    jewel_pommel_arbalest = { name = "Draguljnogrbi samostrel", woodCost = 3, steelCost = 2, goldCost = 1, silverCost = 1, ironCost = 1, ropeCost = 1, jewelCost = 1, time = 20, cost = 4000, attack = 90, happiness = 5, prestige = 32, description = "Samostrel z draguljnim grbičem za visoko plemstvo." },
    royal_grand_arbalest = { name = "Kraljevski veliki samostrel", woodCost = 5, steelCost = 3, goldCost = 2, silverCost = 2, ironCost = 1, ropeCost = 1, jewelCost = 2, pearlCost = 2, time = 27, cost = 8000, attack = 98, happiness = 12, prestige = 62, description = "Veliki kraljevski samostrel z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    arbalest_workshop = { name = "Samostrelarska delavnica", cost = { gold = 300, wood = 160, stone = 140, iron = 6, rope = 6 }, upkeep = 7, qualityBonus = 5 },
    crossbow_loft = { name = "Samostrelska podstrešje", cost = { gold = 1100, wood = 320, stone = 280, steel = 6, silver = 6 }, upkeep = 26, qualityBonus = 18 },
    master_arbalest_atelier = { name = "Mojstrski samostrelski atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_arbalest_palace = { name = "Kraljevska samostrelska palača", cost = { gold = 12200, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
ArbalestMaker.woodStock = 16; ArbalestMaker.ironStock = 12; ArbalestMaker.steelStock = 10; ArbalestMaker.ropeStock = 10; ArbalestMaker.silverStock = 6; ArbalestMaker.goldStock = 6; ArbalestMaker.jewelStock = 4; ArbalestMaker.pearlStock = 4
ArbalestMaker.productStock = {}; ArbalestMaker.buildings = {}; ArbalestMaker.maker = nil; ArbalestMaker.activeMaking = {}; ArbalestMaker.totalProducts = 0; ArbalestMaker.dayTimer = 0
function ArbalestMaker.init() ArbalestMaker.woodStock=16; ArbalestMaker.ironStock=12; ArbalestMaker.steelStock=10; ArbalestMaker.ropeStock=10; ArbalestMaker.silverStock=6; ArbalestMaker.goldStock=6; ArbalestMaker.jewelStock=4; ArbalestMaker.pearlStock=4; ArbalestMaker.productStock={}; ArbalestMaker.buildings={}; ArbalestMaker.maker=nil; ArbalestMaker.activeMaking={}; ArbalestMaker.totalProducts=0; ArbalestMaker.dayTimer=0; print("[ArbalestMaker] Royal Arbalest Maker System initialized (6 products, 4 buildings)") end
function ArbalestMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ArbalestMaker.maker={name=n or ("Samostrelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Samostrelar najet: %s (spretnost: %d)",ArbalestMaker.maker.name,s),"success") end; return true end
function ArbalestMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ArbalestMaker.build(id) local ok,e=ArbalestMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ArbalestMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ArbalestMaker.getQualityBonus() local b=0; for _,bd in ipairs(ArbalestMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ArbalestMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ArbalestMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and ArbalestMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and ArbalestMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.ropeCost and ArbalestMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and ArbalestMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ArbalestMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ArbalestMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ArbalestMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ArbalestMaker.buildings==0 then return false,"Potrebna samostrelarska delavnica" end; if not ArbalestMaker.maker then return false,"Potreben samostrelar" end; return true end
function ArbalestMaker.make(pt,qty) qty=qty or 1; local ok,e=ArbalestMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ArbalestMaker.woodStock=ArbalestMaker.woodStock-d.woodCost*qty end; if d.ironCost then ArbalestMaker.ironStock=ArbalestMaker.ironStock-d.ironCost*qty end; if d.steelCost then ArbalestMaker.steelStock=ArbalestMaker.steelStock-d.steelCost*qty end; if d.ropeCost then ArbalestMaker.ropeStock=ArbalestMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then ArbalestMaker.silverStock=ArbalestMaker.silverStock-d.silverCost*qty end; if d.goldCost then ArbalestMaker.goldStock=ArbalestMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ArbalestMaker.jewelStock=ArbalestMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ArbalestMaker.pearlStock=ArbalestMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ArbalestMaker.maker then t=math.max(1,t-math.floor(ArbalestMaker.maker.skill/12)) end; table.insert(ArbalestMaker.activeMaking,{id="arbalest_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ArbalestMaker.completeMaking(m) local q=1.0+(ArbalestMaker.getQualityBonus()/100); if ArbalestMaker.maker then q=q+(ArbalestMaker.maker.skill/140) end; q=math.min(2.5,q); ArbalestMaker.productStock[m.productType]=(ArbalestMaker.productStock[m.productType] or 0)+m.quantity; ArbalestMaker.totalProducts=ArbalestMaker.totalProducts+m.quantity; if m.attack>0 and _G.state then _G.state.attack=(_G.state.attack or 0)+m.attack end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ArbalestMaker.maker then ArbalestMaker.maker.itemsMade=ArbalestMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ArbalestMaker.maker.skill=math.min(100,ArbalestMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Samostrel izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"arbalest.completed",{productName=m.productName,attack=m.attack,prestige=m.prestige,happiness=m.happiness}) end end
function ArbalestMaker.update(dt) if not _G.state then return end; ArbalestMaker.dayTimer=ArbalestMaker.dayTimer+dt; if ArbalestMaker.dayTimer>=30 then ArbalestMaker.dayTimer=0; for i=#ArbalestMaker.activeMaking,1,-1 do local m=ArbalestMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ArbalestMaker.completeMaking(m); table.remove(ArbalestMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ArbalestMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ArbalestMaker.maker then tu=tu+17 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ArbalestMaker.getStats() return {woodStock=ArbalestMaker.woodStock,ironStock=ArbalestMaker.ironStock,steelStock=ArbalestMaker.steelStock,ropeStock=ArbalestMaker.ropeStock,silverStock=ArbalestMaker.silverStock,goldStock=ArbalestMaker.goldStock,jewelStock=ArbalestMaker.jewelStock,pearlStock=ArbalestMaker.pearlStock,productStock=ArbalestMaker.productStock,numBuildings=#ArbalestMaker.buildings,hasMaker=ArbalestMaker.maker~=nil,makerName=ArbalestMaker.maker and ArbalestMaker.maker.name or "—",makerSkill=ArbalestMaker.maker and ArbalestMaker.maker.skill or 0,activeMaking=#ArbalestMaker.activeMaking,totalProducts=ArbalestMaker.totalProducts} end
return ArbalestMaker
